/**
 * Device config for internal user auto login. Only one config per device is stored.
 */
export class DeviceConfig implements CredentialsStorage, UsageTestStorage {
	public static readonly Version = 3
	public static readonly LocalStorageKey = "tutanotaConfig"

	private config: Config

	constructor(private readonly version: number, private readonly storage: ConfigStorage | null) {
		this.config = defaultConfig(version)
		this._load()
	}

	store(persistentCredentials: PersistentCredentials): void {
		const userId = persistentCredentials.credentialInfo.userId
		const existing = this.config._credentials.get(userId)
		const updated = existing?.databaseKey
			? {...persistentCredentials, databaseKey: existing.databaseKey}
			: persistentCredentials
		if (JSON.stringify(existing) !== JSON.stringify(updated)) {
			this.config._credentials.set(userId, updated)
			this.writeToStorage()
		}
	}

	loadByUserId(userId: Id): PersistentCredentials | null {
		return this.config._credentials.get(userId) ?? null
	}

	loadAll(): Array<PersistentCredentials> {
		return Array.from(this.config._credentials.values())
	}

	deleteByUserId(userId: Id): void {
		if (this.config._credentials.delete(userId)) {
			this.writeToStorage()
		}
	}

	_load(): void {
		this.config = defaultConfig(this.version)
		let loadedConfig: Record<string, any> | null = null
		try {
			const stored = this.storage?.getItem(DeviceConfig.LocalStorageKey)
			loadedConfig = stored != null ? this._parseConfig(stored) : null
		} catch (e) {
			console.warn("Could not read device config", e)
		}

		let changed = false
		if (loadedConfig !== null) {
			if (typeof loadedConfig._version !== "number" || loadedConfig._version < this.version) {
				migrateConfig(loadedConfig, this.version)
				changed = true
			}
			this.config = this.deserializeConfig(loadedConfig)
		}

		if (!this.config._signupToken) {
			const bytes = new Uint8Array(6)
			window.crypto.getRandomValues(bytes)
			this.config._signupToken = uint8ArrayToBase64(bytes)
			changed = true
		}

		if (changed) this.writeToStorage()
	}

	_parseConfig(loadedConfigString: string): Record<string, any> | null {
		try {
			const parsed: unknown = JSON.parse(loadedConfigString)
			return isRecord(parsed) ? parsed : null
		} catch (e) {
			console.warn("Could not parse device config")
			return null
		}
	}

	private deserializeConfig(loaded: Record<string, any>): Config {
		const config = defaultConfig(this.version)
		if (isRecord(loaded._credentials)) config._credentials = new Map(Object.entries(loaded._credentials))
		if (Array.isArray(loaded._scheduledAlarmUsers)) config._scheduledAlarmUsers = loaded._scheduledAlarmUsers
		if (loaded._themeId != null) config._themeId = loaded._themeId
		if (loaded._language !== undefined) config._language = loaded._language
		if (isRecord(loaded._defaultCalendarView)) config._defaultCalendarView = loaded._defaultCalendarView
		if (isRecord(loaded._hiddenCalendars)) config._hiddenCalendars = loaded._hiddenCalendars
		if (typeof loaded._signupToken === "string") config._signupToken = loaded._signupToken
		if (loaded._credentialEncryptionMode !== undefined) config._credentialEncryptionMode = loaded._credentialEncryptionMode
		if (loaded._encryptedCredentialsKey !== undefined) config._encryptedCredentialsKey = loaded._encryptedCredentialsKey
		if (loaded._testDeviceId !== undefined) config._testDeviceId = loaded._testDeviceId
		if (loaded._testAssignments !== undefined) config._testAssignments = loaded._testAssignments
		return config
	}

	getSignupToken(): string {
		return this.config._signupToken
	}

	hasScheduledAlarmsForUser(userId: Id): boolean {
		return this.config._scheduledAlarmUsers.includes(userId)
	}

	setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this.config._scheduledAlarmUsers.indexOf(userId)
		if (setScheduled && scheduledIndex === -1) {
			this.config._scheduledAlarmUsers.push(userId)
			this.writeToStorage()
		} else if (!setScheduled && scheduledIndex !== -1) {
			this.config._scheduledAlarmUsers.splice(scheduledIndex, 1)
			this.writeToStorage()
		}
	}

	setNoAlarmsScheduled() {
		if (this.config._scheduledAlarmUsers.length > 0) {
			this.config._scheduledAlarmUsers = []
			this.writeToStorage()
		}
	}

	getLanguage(): LanguageCode | null {
		return this.config._language
	}

	setLanguage(language: LanguageCode | null) {
		if (this.config._language !== language) {
			this.config._language = language
			this.writeToStorage()
		}
	}

	private writeToStorage(): void {
		try {
			this.storage?.setItem(DeviceConfig.LocalStorageKey, JSON.stringify({
				...this.config,
				_credentials: Object.fromEntries(this.config._credentials),
			}))
		} catch (e) {
			// Storage can be unavailable or full, for example in Safari private browsing.
			console.log("could not store config", e)
		}
	}

	getTheme(): ThemeId {
		return this.config._themeId
	}

	setTheme(theme: ThemeId) {
		if (this.config._themeId !== theme) {
			this.config._themeId = theme

			this.writeToStorage()
		}
	}

	getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this.config._defaultCalendarView[userId]
	}

	setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this.config._defaultCalendarView[userId] !== defaultView) {
			this.config._defaultCalendarView[userId] = defaultView

			this.writeToStorage()
		}
	}

	getHiddenCalendars(user: Id): Id[] {
		return Object.prototype.hasOwnProperty.call(this.config._hiddenCalendars, user) ? this.config._hiddenCalendars[user] : []
	}

	setHiddenCalendars(user: Id, calendars: Id[]) {
		const existing = this.config._hiddenCalendars[user]
		if (!existing || existing.length !== calendars.length || existing.some((id, index) => id !== calendars[index])) {
			this.config._hiddenCalendars[user] = calendars

			this.writeToStorage()
		}
	}

	getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this.config._credentialEncryptionMode
	}

	setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		if (this.config._credentialEncryptionMode !== encryptionMode) {
			this.config._credentialEncryptionMode = encryptionMode
			this.writeToStorage()
		}
	}

	getCredentialsEncryptionKey(): Uint8Array | null {
		return this.config._encryptedCredentialsKey ? base64ToUint8Array(this.config._encryptedCredentialsKey) : null
	}

	setCredentialsEncryptionKey(value: Uint8Array | null) {
		const key = value ? uint8ArrayToBase64(value) : null
		if (this.config._encryptedCredentialsKey !== key) {
			this.config._encryptedCredentialsKey = key
			this.writeToStorage()
		}
	}

	async getTestDeviceId(): Promise<string | null> {
		return this.config._testDeviceId
	}

	async storeTestDeviceId(testDeviceId: string): Promise<void> {
		if (this.config._testDeviceId !== testDeviceId) {
			this.config._testDeviceId = testDeviceId
			this.writeToStorage()
		}
	}

	async getAssignments(): Promise<PersistedAssignmentData | null> {
		return this.config._testAssignments
	}

	async storeAssignments(persistedAssignmentData: PersistedAssignmentData): Promise<void> {
		if (JSON.stringify(this.config._testAssignments) !== JSON.stringify(persistedAssignmentData)) {
			this.config._testAssignments = persistedAssignmentData
			this.writeToStorage()
		}
	}
}


export function migrateConfig(loadedConfig: any, version: number = DeviceConfig.Version): void {
	if (typeof loadedConfig._version !== "number") loadedConfig._version = 1
	if (loadedConfig._version < 3 && version >= 3) migrateConfigV2to3(loadedConfig)
	if (loadedConfig._version < version) loadedConfig._version = version
}

/**
 * Migrate from V2 of the config to V3
 *
 * Exported for testing
 */
export function migrateConfigV2to3(loadedConfig: any): void {
	if (Array.isArray(loadedConfig._credentials)) {
		const credentials: Record<Id, PersistentCredentials> = {}
		for (const oldCredential of loadedConfig._credentials) {
			if (!isRecord(oldCredential)) continue
			const userId = oldCredential.userId
			if (typeof userId !== "string") continue
			const internal = typeof oldCredential.mailAddress === "string" && oldCredential.mailAddress.includes("@")
			credentials[userId] = {
				credentialInfo: {login: internal ? oldCredential.mailAddress : userId, userId, type: internal ? "internal" : "external"},
				accessToken: oldCredential.accessToken,
				encryptedPassword: oldCredential.encryptedPassword,
				...(Object.prototype.hasOwnProperty.call(oldCredential, "databaseKey") ? {databaseKey: oldCredential.databaseKey} : {}),
			} as PersistentCredentials
		}
		loadedConfig._credentials = credentials
	} else if (!isRecord(loadedConfig._credentials)) {
		loadedConfig._credentials = {}
	}
	if (loadedConfig._themeId == null && loadedConfig._theme != null) loadedConfig._themeId = loadedConfig._theme
	delete loadedConfig._theme
	loadedConfig._version = 3
}

